1	import 'dart:async';
2	
3	import 'package:flutter/foundation.dart';
4	import 'package:flutter_riverpod/flutter_riverpod.dart';
5	import 'package:geolocator/geolocator.dart';
6	import 'package:here_sdk/core.dart';
7	import 'package:here_sdk/mapview.dart';
8	import 'package:here_sdk/navigation.dart' hide Navigator;
9	import 'package:here_sdk/routing.dart' show ManeuverAction, Route;
10	
11	import 'package:ukcheckpoints_app/core/utils/logger.dart';
12	
13	class GuidanceState {
14	  final int currentManeuverIndex;
15	  final int remainingDistanceMeters;
16	  final Duration remainingEta;
17	  final String? currentManeuverText;
18	  final ManeuverAction? currentAction;
19	  final int? nextManeuverDistance;
20	  final int? nextManeuverIndex;
21	  final String? nextManeuverText;
22	  final ManeuverAction? nextManeuverAction;
23	  final bool isActive;
24	  final bool destinationReached;
25	
26	  const GuidanceState({
27	    this.currentManeuverIndex = 0,
28	    this.remainingDistanceMeters = 0,
29	    this.remainingEta = Duration.zero,
30	    this.currentManeuverText,
31	    this.currentAction,
32	    this.nextManeuverDistance,
33	    this.nextManeuverIndex,
34	    this.nextManeuverText,
35	    this.nextManeuverAction,
36	    this.isActive = false,
37	    this.destinationReached = false,
38	  });
39	}
40	
41	class NavigationGuidanceNotifier extends StateNotifier<GuidanceState> {
42	  VisualNavigator? _visualNavigator;
43	  StreamSubscription<Position>? _locationSub;
44	  int _previousManeuverIndex = -1;
45	
46	  NavigationGuidanceNotifier() : super(const GuidanceState());
47	
48	  @override
49	  void dispose() {
50	    stopGuidance();
51	    super.dispose();
52	  }
53	
54	  void startRendering(HereMapController mapController) {
55	    try {
56	      _visualNavigator = VisualNavigator();
57	      _visualNavigator!.startRendering(mapController);
58	    } catch (e, st) {
59	      AppLogger.error('VisualNavigator init failed', error: e, stackTrace: st);
60	    }
61	  }
62	
63	  void stopRendering() {
64	    _visualNavigator?.stopRendering();
65	  }
66	
67	  void startGuidance({
68	    required Route route,
69	    required Stream<Position> locationStream,
70	  }) {
71	    final nav = _visualNavigator;
72	    if (nav == null) return;
73	
74	    nav.eventTextListener = EventTextListener((EventText event) {});
75	
76	    nav.routeProgressListener =
77	        RouteProgressListener((RouteProgress progress) {
78	      final sections = progress.sectionProgress;
79	      final remainingDistance =
80	          sections.isNotEmpty ? sections.last.remainingDistanceInMeters : 0;
81	      final remainingEta =
82	          sections.isNotEmpty ? sections.last.remainingDuration : Duration.zero;
83	
84	      final maneuvers = progress.maneuverProgress;
85	      final nextDist =
86	          maneuvers.isNotEmpty
87	              ? maneuvers.first.remainingDistanceInMeters
88	              : null;
89	      final curIndex =
90	          maneuvers.isNotEmpty ? maneuvers.first.maneuverIndex : -1;
91	
92	      String? curText;
93	      ManeuverAction? curAction;
94	      if (curIndex >= 0) {
95	        final m = nav.getManeuver(curIndex);
96	        curText = m?.text;
97	        curAction = m?.action;
98	      }
99	
100	      int? lookAheadIndex;
101	      String? lookAheadText;
102	      ManeuverAction? lookAheadAction;
103	      if (maneuvers.length > 1) {
104	        lookAheadIndex = maneuvers[1].maneuverIndex;
105	        if (lookAheadIndex >= 0) {
106	          final m = nav.getManeuver(lookAheadIndex);
107	          lookAheadText = m?.text;
108	          lookAheadAction = m?.action;
109	        }
110	      }
111	
112	      if (curIndex != _previousManeuverIndex) {
113	        _previousManeuverIndex = curIndex;
114	      }
115	
116	      state = GuidanceState(
117	        currentManeuverIndex: curIndex,
118	        remainingDistanceMeters: remainingDistance,
119	        remainingEta: remainingEta,
120	        currentManeuverText: curText,
121	        currentAction: curAction,
122	        nextManeuverDistance: nextDist,
123	        nextManeuverIndex: lookAheadIndex,
124	        nextManeuverText: lookAheadText,
125	        nextManeuverAction: lookAheadAction,
126	        isActive: true,
127	      );
128	    });
129	
130	    nav.routeDeviationListener =
131	        RouteDeviationListener((RouteDeviation deviation) {
132	      debugPrint('Route deviation: ${deviation.toString()}');
133	    });
134	
135	    nav.destinationReachedListener = DestinationReachedListener(() {
136	      state = GuidanceState(isActive: false, destinationReached: true);
137	    });
138	
139	    nav.route = route;
140	
141	    _locationSub?.cancel();
142	    _locationSub = locationStream.listen((position) {
143	      final location = Location.withCoordinates(
144	        GeoCoordinates(position.latitude, position.longitude),
145	      );
146	      location.time = position.timestamp;
147	      location.speedInMetersPerSecond = position.speed;
148	      nav.onLocationUpdated(location);
149	    });
150	  }
151	
152	  void stopGuidance() {
153	    final nav = _visualNavigator;
154	    if (nav != null) {
155	      nav.route = null;
156	      nav.routeProgressListener = null;
157	      nav.eventTextListener = null;
158	      nav.routeDeviationListener = null;
159	      nav.destinationReachedListener = null;
160	    }
161	    _locationSub?.cancel();
162	    _locationSub = null;
163	    state = const GuidanceState();
164	  }
165	}
166	
167	final navigationGuidanceProvider = StateNotifierProvider<
168	    NavigationGuidanceNotifier,
169	    GuidanceState>((ref) {
170	  return NavigationGuidanceNotifier();
171	});
