11	String _formatDuration(Duration d) {
12	  final hours = d.inHours;
13	  final mins = d.inMinutes.remainder(60);
14	  return hours > 0 ? '$hours h $mins min' : '$mins min';
15	}
16	
17	String _formatDistance(int meters) {
18	  if (meters >= 1000) {
19	    return '${(meters / 1609.34).toStringAsFixed(1)} mi';
20	  }
21	  return '${(meters * 3.28084).round()} ft';
22	}
23	
24	double _calcProgress(CalculatedRoute route, GuidanceState guidance) {
25	  final total = route.distanceMeters;
26	  if (total <= 0) return 0;
27	  final remaining = guidance.remainingDistanceMeters;
28	  return (1.0 - (remaining / total)).clamp(0.0, 1.0);
29	}
