31	class NavigationSheet extends StatefulWidget {
32	  final double maxHeight;
33	  final ValueChanged<double>? onHeightChanged;
34	  final Future<void> Function()? onExpandRequested;
35	  final Widget? child;
36	  final CalculatedRoute? route;
37	  final bool isCalculating;
38	  final VoidCallback? onCancelRoute;
39	  final Map<int, List<Checkpoint>> routeCheckpoints;
