61	class NavigationSheetState extends State<NavigationSheet> {
62	  bool _expanded = false;
63	  bool _showExpanded = false;
64	
65	  double get _collapsedHeight {
66	    if (widget.guidance.isActive) return 188;
67	    if (widget.route != null) return 110;
68	    return 84;
69	  }
70	
71	  double get _currentHeight =>
72	      _expanded ? widget.maxHeight * 0.5 : _collapsedHeight;
73	
74	  @override
75	  void initState() {
76	    super.initState();
77	    WidgetsBinding.instance.addPostFrameCallback((_) {
78	      widget.onHeightChanged?.call(_collapsedHeight);
79	    });
80	  }
81	
82	  void _handleTap() {
83	    if (!_expanded) {
84	      _doExpand();
85	    } else {
86	      _doCollapse();
87	    }
88	    _notifyHeight();
89	  }
90	
91	  void expand() {
92	    _doExpand();
93	    _notifyHeight();
94	  }
95	
96	  void collapse() {
97	    _doCollapse();
98	    _notifyHeight();
99	  }
100	
101	  void _doExpand() {
102	    setState(() {
103	      _expanded = true;
104	      _showExpanded = false;
105	    });
106	    Future.delayed(ThemeMotion.durBase, () {
107	      if (mounted && _expanded) {
108	        setState(() => _showExpanded = true);
109	      }
110	    });
111	  }
112	
113	  void _doCollapse() {
114	    setState(() {
115	      _expanded = false;
116	      _showExpanded = false;
117	    });
118	  }
119	
120	  void _notifyHeight() {
121	    WidgetsBinding.instance.addPostFrameCallback((_) {
122	      widget.onHeightChanged?.call(_currentHeight);
123	    });
124	  }
125	
126	  @override
127	  Widget build(BuildContext context) {
128	    final bottomSafe = MediaQuery.of(context).padding.bottom;
129	
130	    return ClipRRect(
131	      borderRadius: const BorderRadius.vertical(
132	        top: Radius.circular(ThemeRadius.r2xl),
133	      ),
134	      child: AnimatedContainer(
135	        duration: ThemeMotion.durSlow,
136	        curve: ThemeMotion.smooth,
137	        height: _currentHeight + bottomSafe,
138	        decoration: const BoxDecoration(
139	          color: ThemeColors.bgRaised,
140	          boxShadow: ThemeShadows.lg,
141	        ),
142	        child: GestureDetector(
143	          behavior: HitTestBehavior.translucent,
144	          onVerticalDragEnd: (details) {
145	            if (details.primaryVelocity == null) return;
146	            if (details.primaryVelocity! < -300) {
147	              _doExpand();
148	            } else if (details.primaryVelocity! > 300) {
149	              _doCollapse();
150	            }
151	            _notifyHeight();
152	          },
153	          child: Column(
154	            mainAxisSize: MainAxisSize.min,
155	            children: [
156	              const _DragHandle(),
157	              if (_expanded)
158	                Expanded(child: _buildContent())
159	              else
160	                Flexible(child: _buildContent()),
161	            ],
162	          ),
163	        ),
164	      ),
165	    );
166	  }
167	
168	  Widget _buildContent() {
169	    final guidance = widget.guidance;
170	    final route = widget.route;
171	
172	    if (widget.isCalculating) {
173	      return const Center(
174	        child: Padding(
175	          padding: EdgeInsets.all(ThemeSpacing.sp5),
176	          child: Row(
177	            mainAxisAlignment: MainAxisAlignment.center,
178	            children: [
179	              SizedBox(
180	                width: 20,
181	                height: 20,
182	                child: CircularProgressIndicator(strokeWidth: 2),
