186	            ],
187	          ),
188	        ),
189	      );
190	    }
191	
192	    if (guidance.isActive && _showExpanded && route != null) {
193	      return _GuidanceExpanded(
194	        guidance: guidance,
195	        route: route,
196	        routeCheckpoints: widget.routeCheckpoints,
197	        onCancel: widget.onCancelRoute,
198	        onCheckpointTapped: widget.onRouteCheckpointTapped,
199	      );
200	    }
201	
202	    if (guidance.isActive && route != null) {
203	      return _RouteWithProgress(
204	        duration: guidance.remainingEta,
205	        distance: guidance.remainingDistanceMeters,
206	        progress: _calcProgress(route, guidance),
207	        showChevron: true,
208	        onCancel: widget.onCancelRoute,
209	      );
