import 'dart:async';

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:here_sdk/core.dart';
import 'package:here_sdk/routing.dart';

import 'package:ukcheckpoints_app/core/utils/logger.dart';
import 'package:ukcheckpoints_app/features/map/data/vehicle_profile_model.dart';
import 'package:ukcheckpoints_app/features/map/data/vehicle_profile_service.dart';

class CalculatedRoute {
  final Route route;
  final int distanceMeters;
  final Duration eta;
  final List<Maneuver> maneuvers;

  const CalculatedRoute({
    required this.route,
    required this.distanceMeters,
    required this.eta,
    required this.maneuvers,
  });
}

class RouteCalculationNotifier extends StateNotifier<AsyncValue<CalculatedRoute?>> {
  final RoutingEngine _routingEngine = RoutingEngine();
  final VehicleProfileService _profileService = VehicleProfileService();

  RouteCalculationNotifier() : super(const AsyncData(null));

  @override
  void dispose() {
    super.dispose();
  }

  Future<void> calculate({
    required GeoCoordinates origin,
    required GeoCoordinates destination,
    required VehicleProfileModel profile,
  }) async {
    state = const AsyncLoading();

    try {
      final waypoints = [
        Waypoint(origin),
        Waypoint(destination),
      ];

      final routingOptions =
          _profileService.buildRoutingOptions(profile);

      final completer = Completer<AsyncValue<CalculatedRoute?>>();

      _routingEngine.calculateRouteWithRoutingOptions(
        waypoints,
        routingOptions,
        (RoutingError? error, List<Route>? routeList) {
          if (error != null || routeList == null || routeList.isEmpty) {
            if (!completer.isCompleted) {
              completer.complete(
                AsyncError(
                  RouteCalculationError(
                    'Could not calculate route. ${error?.name ?? ""}',
                  ),
                  StackTrace.current,
                ),
              );
            }
            return;
          }

          final route = routeList.first;
          final maneuvers = <Maneuver>[];
          for (final section in route.sections) {
            maneuvers.addAll(section.maneuvers);
          }

          if (!completer.isCompleted) {
            completer.complete(
              AsyncData(
                CalculatedRoute(
                  route: route,
                  distanceMeters: route.lengthInMeters,
                  eta: route.duration,
                  maneuvers: maneuvers,
                ),
              ),
            );
          }
        },
      );

      state = await completer.future;
    } catch (e, st) {
      AppLogger.error('Route calculation failed', error: e, stackTrace: st);
      state = AsyncError(
        RouteCalculationError(e.toString()),
        st,
      );
    }
  }

  void reset() {
    state = const AsyncData(null);
  }
}

class RouteCalculationError implements Exception {
  final String message;
  const RouteCalculationError(this.message);

  @override
  String toString() => message;
}

final routeCalculationProvider = StateNotifierProvider<
    RouteCalculationNotifier,
    AsyncValue<CalculatedRoute?>>((ref) {
  return RouteCalculationNotifier();
});

import 'dart:async';

