class MapScreen extends ConsumerStatefulWidget {
  const MapScreen({super.key});

  @override
  ConsumerState<MapScreen> createState() => _MapScreenState();
}

class _MapScreenState extends ConsumerState<MapScreen> {
  MapImage? _activeIcon;
  MapImage? _inactiveIcon;
  MapImage? _policeIcon;
  MapImage? _unknownIcon;

  List<Checkpoint>? _pendingCheckpoints;

  double _sheetHeight = 120;

  void _onSheetHeightChanged(double height) {
    if ((height - _sheetHeight).abs() < 1) return;
    setState(() => _sheetHeight = height);
  }

  final _navSheetKey = GlobalKey<NavigationSheetState>();

  @override
  void initState() {
    super.initState();
    unawaited(_loadIcons());
  }

  Future<void> _loadIcons() async {
    _activeIcon = await _loadImage('assets/images/marker_active.png');
    _inactiveIcon = await _loadImage('assets/images/marker_inactive.png');
    _policeIcon = await _loadImage('assets/images/marker_police.png');
    _unknownIcon = await _loadImage('assets/images/marker_unknown.png');
    if (!mounted) return;

    setState(() {});

    final checkpoints =
        _pendingCheckpoints ??
        ref.read(checkpointNotifierProvider).value?.checkpoints ??
        [];
    if (checkpoints.isNotEmpty) {
      _updateMapCheckpoints(checkpoints);
      _pendingCheckpoints = null;
    }
  }

  void _updateMapCheckpoints(List<Checkpoint> checkpoints) {
    final active = _activeIcon;
    final inactive = _inactiveIcon;
    final police = _policeIcon;
    final unknown = _unknownIcon;

    if (active == null ||
        inactive == null ||
        police == null ||
        unknown == null) {
      _pendingCheckpoints = checkpoints;
      return;
    }

    ref.read(mapControllerProvider.notifier).updateCheckpoints(checkpoints, {
      ContributionStatusEnum.ACTIVE: active,
      ContributionStatusEnum.INACTIVE: inactive,
      ContributionStatusEnum.POLICE_ALERT: police,
      ContributionStatusEnum.UNKNOWN: unknown,
    });
  }

  Future<MapImage> _loadImage(String asset) async {
    final bytes = await rootBundle.load(asset);
    return MapImage.withPixelDataAndImageFormat(
      bytes.buffer.asUint8List(),
      ImageFormat.png,
    );
  }

  Future<void> _onExpandRequested() async {
    final service = ref.read(vehicleProfileRepositoryProvider);
    final count = await service.count();
    if (!mounted) return;

    if (count == 0) {
      _openProfileCreateSheet();
    } else {
      _openProfileSelectSheet();
    }
  }

  void _openProfileCreateSheet() {
    final service = ref.read(vehicleProfileRepositoryProvider);
    unawaited(
      showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        builder:
            (_) => VehicleProfileSheet(
              service: service,
              onProfileCreated: () {
                _navSheetKey.currentState?.expand();
              },
            ),
      ),
    );
  }

  void _openProfileSelectSheet() {
    final service = ref.read(vehicleProfileRepositoryProvider);
    unawaited(
      showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        builder:
            (_) => VehicleProfileSelectSheet(
              service: service,
              onProfileReady: () {
                _navSheetKey.currentState?.expand();
              },
            ),
      ),
    );
  }

  void _onMapCreated(HereMapController hereMapController) {
    ref.read(mapControllerProvider.notifier).setController(
      hereMapController,
      _onCheckpointTapped,
    );

    hereMapController.camera.addListener(
      MapCameraListener((cameraState) {
        ref.read(mapBearingProvider.notifier).state =
            cameraState.orientationAtTarget.bearing;
      }),
    );

    ref
        .read(navigationGuidanceProvider.notifier)
        .startRendering(hereMapController);
  }

  void _onCheckpointTapped(String checkpointId) {
    final checkpoints =
        ref.read(checkpointNotifierProvider).value?.checkpoints ?? [];
    final checkpoint =
        checkpoints.where((c) => c.id == checkpointId).firstOrNull;
    if (checkpoint != null && context.mounted) {
      unawaited(
        showModalBottomSheet<void>(
          context: context,
          isScrollControlled: true,
          backgroundColor: Colors.transparent,
          builder: (context) => CheckpointActionSheet(checkpoint: checkpoint),
        ),
      );
    }
  }

  void _onStartNavigation(VehicleProfileModel profile) {
    final nav = ref.read(navigationRouteProvider);
    if (nav.origin == null || nav.destination == null) return;

    unawaited(
      ref.read(routeCalculationProvider.notifier).calculate(
        origin: nav.origin!,
        destination: nav.destination!,
        profile: profile,
      ),
    );
  }

  void _onCancelRoute() {
    ref.read(routeCalculationProvider.notifier).reset();
    ref.read(mapControllerProvider.notifier).clearRoute();
    ref.read(navigationGuidanceProvider.notifier).stopGuidance();
  }

  Map<ContributionStatusEnum, MapImage>? _getIconMap() {
    final active = _activeIcon;
    final inactive = _inactiveIcon;
    final police = _policeIcon;
    final unknown = _unknownIcon;
    if (active == null ||
        inactive == null ||
        police == null ||
        unknown == null) {
      return null;
    }
    return {
      ContributionStatusEnum.ACTIVE: active,
      ContributionStatusEnum.INACTIVE: inactive,
      ContributionStatusEnum.POLICE_ALERT: police,
      ContributionStatusEnum.UNKNOWN: unknown,
    };
  }

  void _renderAllCheckpoints(WidgetRef ref) {
    final checkpoints =
        ref.read(checkpointNotifierProvider).value?.checkpoints ?? [];
    _updateMapCheckpoints(checkpoints);
  }

  void _onRouteCheckpointTapped(Checkpoint checkpoint) {
    ref.read(mapControllerProvider.notifier).focusOnCheckpoint(checkpoint);
    _navSheetKey.currentState?.collapse();
  }

  @override
  Widget build(BuildContext context) {
    ref
      ..listen(userLocationStreamProvider, (previous, next) {
        final position = next.value;
        if (position != null) {
          ref.read(mapControllerProvider.notifier).updateLocation(
            GeoCoordinates(position.latitude, position.longitude),
          );
        }
      })
      ..listen(checkpointNotifierProvider, (previous, next) {
        next.whenData((data) {
          _updateMapCheckpoints(data.checkpoints);
        });
      });

    final locationAsync = ref.watch(userLocationStreamProvider);
    final userPos = locationAsync.value;
    final userCoords =
        userPos != null
            ? GeoCoordinates(userPos.latitude, userPos.longitude)
            : null;

    final routeState = ref.watch(routeCalculationProvider);
    final route = routeState.valueOrNull;
    final isCalculating = routeState is AsyncLoading;
    final guidance = ref.watch(navigationGuidanceProvider);

    ref
      ..watch(nearbyCheckpointProvider)
      ..listen(routeCalculationProvider, (prev, next) {
      next.whenData((r) {
        if (r != null) {
          ref.read(mapControllerProvider.notifier).clearRoute();
          ref.read(mapControllerProvider.notifier).drawRoute(r.route.geometry);
          _navSheetKey.currentState?.collapse();
          final origin = ref.read(navigationRouteProvider).origin;
          if (origin != null) {
            ref.read(mapControllerProvider.notifier).focusOnCoordinates(origin);
          }
          ref
              .read(navigationGuidanceProvider.notifier)
              .startGuidance(
                route: r.route,
                locationStream: Geolocator.getPositionStream(
                  locationSettings: const LocationSettings(
                    accuracy: LocationAccuracy.bestForNavigation,
                    distanceFilter: 1,
                  ),
                ),
              );
        } else {
          ref.read(mapControllerProvider.notifier).clearRoute();
          ref.read(navigationGuidanceProvider.notifier).stopGuidance();
          _renderAllCheckpoints(ref);
        }
      });
    });

    final routeCheckpoints = ref.watch(routeCheckpointsProvider);

    ref.listen(routeCheckpointsProvider, (prev, next) {
      final icons = _getIconMap();
      if (icons != null && next.isNotEmpty) {
        ref
            .read(mapControllerProvider.notifier)
            .showRouteCheckpoints(
              routeCheckpoints: next,
              icons: icons,
            );
      }
    });

    return Scaffold(
      appBar: const PreferredSize(
        preferredSize: Size.fromHeight(120),

        child: SafeArea(
          bottom: false,
          child: ManeuverBanner(),
        ),
      ),
      body: Stack(
        children: [
          GestureDetector(
            behavior: HitTestBehavior.translucent,
            onTap: () => FocusScope.of(context).unfocus(),
            child: HereMap(onMapCreated: _onMapCreated),
          ),

          Positioned(
            top: 0,
            left: 0,
            right: 0,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (!guidance.isActive)
                  MapSearchBar(
                    onCheckpointSelected: (checkpoint) {
                      ref
                          .read(mapControllerProvider.notifier)
                          .focusOnCheckpoint(checkpoint);
                    },
                  ),
              ],
            ),
          ),

          Positioned(
            bottom: _sheetHeight + 8,
            left: 0,
            right: 0,
            child: const NearbyCheckpointPopup(),
          ),

          Positioned(
            bottom: _sheetHeight + 16,
            left: 16,
            child: const MapSpeedOverlay(),
          ),

          Positioned(
            bottom: _sheetHeight + 16,
            right: 16,
            child: const MapOverlayButtons(),
          ),

          Positioned(
            bottom: 0,
            left: 0,
            right: 0,
            child: NavigationSheet(
              key: _navSheetKey,
              maxHeight: MediaQuery.of(context).size.height,
              onHeightChanged: _onSheetHeightChanged,
              onExpandRequested: _onExpandRequested,
              route: route,
              isCalculating: isCalculating,
              onCancelRoute: _onCancelRoute,
              routeCheckpoints: routeCheckpoints,
              onRouteCheckpointTapped: _onRouteCheckpointTapped,
              guidance: guidance,
              child: NavigationInputBar(
                userLocation: userCoords,
                onNavigate: _onStartNavigation,
              ),
            ),
          ),
        ],
      ),
    );
  }
}

import 'dart:async';

import 'dart:ui' show Color;

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:here_sdk/core.dart';
import 'package:here_sdk/core.engine.dart';
import 'package:here_sdk/gestures.dart';
import 'package:here_sdk/mapview.dart';
import 'package:here_sdk/prefetcher.dart';
import 'package:riverpod_annotation/riverpod_annotation.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';

import 'package:ukcheckpoints_app/core/utils/logger.dart';
import 'package:ukcheckpoints_app/features/map/data/map_preferences_repository.dart';

part 'map_controller.g.dart';

final mapBearingProvider = StateProvider<double>((ref) => 0.0);

final currentMapSchemeProvider = StateProvider<MapScheme>(
  (ref) => MapScheme.normalDay,
);

final isTrafficEnabledProvider = StateProvider<bool>((ref) => false);

final isPublicTransitEnabledProvider = StateProvider<bool>((ref) => false);

@Riverpod(keepAlive: true)
class MapController extends _$MapController {
  LocationIndicator? _locationIndicator;
  GeoCoordinates? _lastLocation;

  // Keyed by checkpointId for O(1) diffing.
  final Map<String, MapMarker> _markerById = {};

  PolygonPrefetcher? _prefetcher;
  bool _hasPrefetched = false;

  @override
  HereMapController? build() {
    ref.onDispose(() {
      _locationIndicator = null;
      _markerById.clear();
    });
    return null;
  }

  void setController(
    HereMapController controller,
    void Function(String) onCheckpointTap,
  ) {
    state = controller;
    _setupLocationIndicator(controller);
    _setupGestureListeners(controller, onCheckpointTap);
    unawaited(_loadAndApplyPreferences());
  }

  Future<void> _loadAndApplyPreferences() async {
    final prefs = ref.read(mapPreferencesRepositoryProvider);
    final schemeName = await prefs.getMapScheme();
    final trafficOn = await prefs.isTrafficEnabled();
    final transitOn = await prefs.isPublicTransitEnabled();

    final scheme = MapScheme.values.firstWhere(
      (s) => s.name == schemeName,
      orElse: () => MapScheme.normalDay,
    );

    ref.read(isTrafficEnabledProvider.notifier).state = trafficOn;
    ref.read(isPublicTransitEnabledProvider.notifier).state = transitOn;

    if (state != null) {
      setMapScheme(scheme, refocus: true);
    }
  }

  void _setupGestureListeners(
    HereMapController controller,
    void Function(String) onCheckpointTap,
  ) {
    controller.gestures.tapListener = TapListener((Point2D point) {
      final current = state;
      if (current == null) return;

      current.pick(
        MapSceneMapPickFilter([MapSceneMapPickFilterContentType.mapItems]),
        Rectangle2D(point, Size2D(40, 40)),
        (MapPickResult? result) {
          final marker = result?.mapItems?.markers.firstOrNull;
          if (marker == null) return;
          final id = marker.metadata?.getString('checkpointId');
          if (id != null) onCheckpointTap(id);
        },
      );
    });
  }

  void _setupLocationIndicator(HereMapController controller) {
    _locationIndicator = LocationIndicator.withMapView(controller)
      ..locationIndicatorStyle = LocationIndicatorIndicatorStyle.pedestrian
      ..enable(controller);
  }

  void updateLocation(GeoCoordinates coordinates) {
    final isFirstLocation = _lastLocation == null;
    _lastLocation = coordinates;
    _locationIndicator?.updateLocation(Location.withCoordinates(coordinates));

    if (isFirstLocation) {
      focusOnUserLocation();
      _prefetchAroundLocation(coordinates);
    }
  }

  void _prefetchAroundLocation(GeoCoordinates coords) {
    final engine = SDKNativeEngine.sharedInstance;
    if (engine == null || _hasPrefetched) return;
    _hasPrefetched = true;

    _prefetcher ??= PolygonPrefetcher(engine);
    final polygon = GeoPolygon.withGeoCircle(GeoCircle(coords, 3000));
    _prefetcher!.prefetch(
      polygon,
      PrefetchStatusListener(
        (_) {},
        (error) {
          if (error != null) {
            AppLogger.error(
              'Tile prefetch failed',
              error: error,
              stackTrace: StackTrace.current,
            );
          }
        },
      ),
    );
  }

  void focusOnUserLocation() {
    _animateTo(_lastLocation);
  }

  void focusOnCoordinates(GeoCoordinates coords) {
    _animateTo(coords);
  }

  void _animateTo(GeoCoordinates? coords) {
    if (coords == null || state == null) return;
    final animation = MapCameraAnimationFactory.flyToWithZoom(
      GeoCoordinatesUpdate(coords.latitude, coords.longitude),
      MapMeasure(MapMeasureKind.distanceInMeters, 1000),
      0,
      const Duration(milliseconds: 800),
    );
    state!.camera.startAnimation(animation);
  }

  void resetOrientationToNorth() {
    final controller = state;
    if (controller == null) return;

    final cameraState = controller.camera.state;
    final animation = MapCameraAnimationFactory.flyToWithOrientationAndZoom(
      GeoCoordinatesUpdate(
        cameraState.targetCoordinates.latitude,
        cameraState.targetCoordinates.longitude,
      ),
      GeoOrientationUpdate(0, cameraState.orientationAtTarget.tilt),
      MapMeasure(
        MapMeasureKind.distanceInMeters,
        cameraState.distanceToTargetInMeters,
      ),
      0,
      const Duration(milliseconds: 600),
    );
    controller.camera.startAnimation(animation);

    ref.read(mapBearingProvider.notifier).state = 0.0;
  }

  // Builds a new MapMarker for a checkpoint, embedding its status in metadata
  // so the diff logic can detect when the icon needs refreshing.
  MapMarker _buildMarker(
    Checkpoint checkpoint,
    Map<ContributionStatusEnum, MapImage> icons,
  ) {
    final status = checkpoint.contributions.isNotEmpty
        ? checkpoint.contributions.first.status
        : ContributionStatusEnum.UNKNOWN;
    final icon = icons[status] ?? icons[ContributionStatusEnum.UNKNOWN]!;
    return MapMarker(
      GeoCoordinates(
        checkpoint.latitude.toDouble(),
        checkpoint.longitude.toDouble(),
      ),
      icon,
    )..metadata = (Metadata()
      ..setString('checkpointId', checkpoint.id)
      ..setString('status', status.name));
  }

  ContributionStatusEnum _statusFor(Checkpoint checkpoint) =>
      checkpoint.contributions.isNotEmpty
          ? checkpoint.contributions.first.status
          : ContributionStatusEnum.UNKNOWN;

  // Diffs the current marker set against the incoming checkpoints:
  // only removes stale markers and adds new/changed ones, in batches.
  void updateCheckpoints(
    List<Checkpoint> checkpoints,
    Map<ContributionStatusEnum, MapImage> icons,
  ) {
    final controller = state;
    if (controller == null) return;

    final desired = {for (final c in checkpoints) c.id: c};

    // Remove markers no longer needed.
    final staleIds = _markerById.keys
        .where((id) => !desired.containsKey(id))
        .toList();
    if (staleIds.isNotEmpty) {
      controller.mapScene.removeMapMarkers(
        staleIds.map((id) => _markerById[id]!).toList(),
      );
      staleIds.forEach(_markerById.remove);
    }

    // Add new markers and refresh any whose status changed.
    final toAdd = <MapMarker>[];
    for (final checkpoint in checkpoints) {
      final existing = _markerById[checkpoint.id];
      if (existing != null) {
        final currentStatus = existing.metadata?.getString('status');
        if (currentStatus == _statusFor(checkpoint).name) continue;
        // Status changed — replace.
        controller.mapScene.removeMapMarker(existing);
        _markerById.remove(checkpoint.id);
      }
      final marker = _buildMarker(checkpoint, icons);
      toAdd.add(marker);
      _markerById[checkpoint.id] = marker;
    }
    if (toAdd.isNotEmpty) {
      controller.mapScene.addMapMarkers(toAdd);
    }
  }

  void setMapScheme(MapScheme scheme, {bool refocus = false}) {
    ref.read(currentMapSchemeProvider.notifier).state = scheme;

    unawaited(
      ref.read(mapPreferencesRepositoryProvider).setMapScheme(scheme.name),
    );

    final coordinates = refocus ? _lastLocation : null;

    final options = MapSceneLoadOptionsBuilder().withMapScheme(scheme).build();
    state?.mapScene.loadScene(options, (MapError? error) {
      if (error != null) {
        AppLogger.error(
          'Map scene load failed',
          error: error,
          stackTrace: StackTrace.current,
        );
        return;
      }
      _reapplyFeatures();
      if (coordinates != null) {
        _animateTo(coordinates);
      }
    });
  }

  void _reapplyFeatures() {
    final controller = state;
    if (controller == null) return;

    final scheme = ref.read(currentMapSchemeProvider);
    final trafficOn = ref.read(isTrafficEnabledProvider);
    final transitOn = ref.read(isPublicTransitEnabledProvider);

    if (scheme == MapScheme.satellite) return;

    if (trafficOn) {
      controller.mapScene.enableFeatures({
        MapFeatures.trafficFlow: MapFeatureModes.trafficFlowWithFreeFlow,
        MapFeatures.trafficIncidents: MapFeatureModes.trafficIncidentsAll,
      });
    }
    if (transitOn) {
      controller.mapScene.enableFeatures({
        MapFeatures.publicTransit: MapFeatureModes.publicTransitAll,
      });
    }
  }

  void toggleTrafficFlow() {
    final newValue = !ref.read(isTrafficEnabledProvider);
    ref.read(isTrafficEnabledProvider.notifier).state = newValue;

    unawaited(
      ref.read(mapPreferencesRepositoryProvider).setTrafficEnabled(newValue),
    );

    final controller = state;
    if (controller == null) return;

    if (ref.read(currentMapSchemeProvider) == MapScheme.satellite) return;

    if (newValue) {
      controller.mapScene.enableFeatures({
        MapFeatures.trafficFlow: MapFeatureModes.trafficFlowWithFreeFlow,
        MapFeatures.trafficIncidents: MapFeatureModes.trafficIncidentsAll,
      });
    } else {
      controller.mapScene.disableFeatures([
        MapFeatures.trafficFlow,
        MapFeatures.trafficIncidents,
      ]);
    }
  }

  void togglePublicTransit() {
    final newValue = !ref.read(isPublicTransitEnabledProvider);
    ref.read(isPublicTransitEnabledProvider.notifier).state = newValue;

    unawaited(
      ref
          .read(mapPreferencesRepositoryProvider)
          .setPublicTransitEnabled(newValue),
    );

    final controller = state;
    if (controller == null) return;

    if (ref.read(currentMapSchemeProvider) == MapScheme.satellite) return;

    if (newValue) {
      controller.mapScene.enableFeatures({
        MapFeatures.publicTransit: MapFeatureModes.publicTransitAll,
      });
    } else {
      controller.mapScene.disableFeatures([MapFeatures.publicTransit]);
    }
  }

  void focusOnCheckpoint(Checkpoint checkpoint) {
    final controller = state;
    if (controller == null) return;

    final animation = MapCameraAnimationFactory.flyToWithZoom(
      GeoCoordinatesUpdate(
        checkpoint.latitude.toDouble(),
        checkpoint.longitude.toDouble(),
      ),
      MapMeasure(MapMeasureKind.distanceInMeters, 500),
      0,
      const Duration(milliseconds: 800),
    );
    controller.camera.startAnimation(animation);
  }

  MapPolyline? _routePolyline;

  void drawRoute(GeoPolyline polyline) {
    final controller = state;
    if (controller == null) return;

    clearRoute();

    final lineWidth = MapMeasureDependentRenderSize.withSingleSize(
      RenderSizeUnit.pixels,
      6,
    );
    final representation = MapPolylineSolidRepresentation(
      lineWidth,
      const Color(0xFF2563EB),
      LineCap.round,
    );
    final mapPolyline =
        MapPolyline.withRepresentation(polyline, representation);
    controller.mapScene.addMapPolyline(mapPolyline);
    _routePolyline = mapPolyline;
  }

  void clearRoute() {
    final controller = state;
    final polyline = _routePolyline;
    if (controller == null || polyline == null) return;
    controller.mapScene.removeMapPolylines([polyline]);
    _routePolyline = null;
  }

  // Full replace: batch-remove current markers, batch-add route markers.
  void showRouteCheckpoints({
    required Map<int, List<Checkpoint>> routeCheckpoints,
    required Map<ContributionStatusEnum, MapImage> icons,
  }) {
    final controller = state;
    if (controller == null) return;

    if (_markerById.isNotEmpty) {
      controller.mapScene.removeMapMarkers(_markerById.values.toList());
      _markerById.clear();
    }

    final toAdd = <MapMarker>[];
    for (final checkpoints in routeCheckpoints.values) {
      for (final checkpoint in checkpoints) {
        final marker = _buildMarker(checkpoint, icons);
        toAdd.add(marker);
        _markerById[checkpoint.id] = marker;
      }
    }
    if (toAdd.isNotEmpty) {
      controller.mapScene.addMapMarkers(toAdd);
    }
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_native_splash/flutter_native_splash.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:here_sdk/core.dart';
