24	double _calcProgress(CalculatedRoute route, GuidanceState guidance) {
25	  final total = route.distanceMeters;
26	  if (total <= 0) return 0;
27	  final remaining = guidance.remainingDistanceMeters;
28	  return (1.0 - (remaining / total)).clamp(0.0, 1.0);
29	}
