import 'dart:async';

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:here_sdk/core.dart';
import 'package:here_sdk/search.dart';

import 'package:ukcheckpoints_app/features/map/data/search_repository.dart';
import 'package:ukcheckpoints_app/core/utils/logger.dart';

class DestinationSearchNotifier
    extends StateNotifier<AsyncValue<List<Suggestion>>> {
  final Ref _ref;
  Timer? _debounce;

  DestinationSearchNotifier(this._ref) : super(const AsyncData([]));

  @override
  void dispose() {
    _debounce?.cancel();
    super.dispose();
  }

  void query(String text) {
    _debounce?.cancel();

    if (text.trim().length < 2) {
      state = const AsyncData([]);
      return;
    }

    state = const AsyncLoading();

    _debounce = Timer(const Duration(milliseconds: 300), () async {
      try {
        final engine = _ref.read(searchEngineProvider);
        final query = TextQuery.withArea(
          text.trim(),
          TextQueryArea.withCenter(GeoCoordinates(51.5074, -0.1278)),
        );
        final options = SearchOptions()
          ..languageCode = LanguageCode.enGb
          ..maxItems = 5;

        final completer = Completer<List<Suggestion>>();

        engine.suggestByText(
          query,
          options,
          (SearchError? error, List<Suggestion>? suggestions) {
            if (error != null || suggestions == null) {
              if (!completer.isCompleted) completer.complete([]);
              return;
            }
            final places =
                suggestions
                    .where((s) => s.type == SuggestionType.place)
                    .take(5)
                    .toList();
            if (!completer.isCompleted) completer.complete(places);
          },
        );

        final results = await completer.future;
        state = AsyncData(results);
      } catch (e, st) {
        AppLogger.error('Destination search failed', error: e, stackTrace: st);
        state = const AsyncData([]);
      }
    });
  }

  void clear() {
    _debounce?.cancel();
    state = const AsyncData([]);
  }
}

final destinationSearchProvider = StateNotifierProvider<
    DestinationSearchNotifier,
    AsyncValue<List<Suggestion>>>((ref) {
  return DestinationSearchNotifier(ref);
});

class NavigationRoute {
  final GeoCoordinates? origin;
  final GeoCoordinates? destination;
  final String originLabel;
  final String destinationLabel;

  const NavigationRoute({
    this.origin,
    this.destination,
    this.originLabel = '',
    this.destinationLabel = '',
  });

  NavigationRoute copyWith({
    GeoCoordinates? origin,
    GeoCoordinates? destination,
    String? originLabel,
    String? destinationLabel,
  }) {
    return NavigationRoute(
      origin: origin ?? this.origin,
      destination: destination ?? this.destination,
      originLabel: originLabel ?? this.originLabel,
      destinationLabel: destinationLabel ?? this.destinationLabel,
    );
  }
}

final navigationRouteProvider =
    StateProvider<NavigationRoute>((ref) => const NavigationRoute());

