1	import 'dart:math';
2	
3	import 'package:flutter_riverpod/flutter_riverpod.dart';
4	import 'package:here_sdk/core.dart';
5	import 'package:here_sdk/routing.dart';
6	import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
7	
8	import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';
9	import 'package:ukcheckpoints_app/features/checkpoints/domain/geoutils.dart';
10	import 'package:ukcheckpoints_app/features/map/providers/routing_provider.dart';
11	
12	typedef RouteCheckpointMap = Map<int, List<Checkpoint>>;
13	
14	final routeCheckpointsProvider =
15	    Provider<RouteCheckpointMap>((ref) {
16	  final routeState = ref.watch(routeCalculationProvider);
17	  final checkpointState = ref.watch(checkpointNotifierProvider);
18	
19	  final route = routeState.valueOrNull;
20	  final checkpoints = checkpointState.valueOrNull?.checkpoints;
21	
22	  if (route == null || checkpoints == null || checkpoints.isEmpty) {
23	    return {};
24	  }
25	
26	  return _computeRouteCheckpoints(
27	    route.route.geometry,
28	    route.maneuvers,
29	    checkpoints,
30	  );
31	});
32	
33	RouteCheckpointMap _computeRouteCheckpoints(
34	  GeoPolyline polyline,
35	  List<Maneuver> maneuvers,
36	  List<Checkpoint> checkpoints,
37	) {
38	  final result = <int, List<Checkpoint>>{};
39	  final vertices = polyline.vertices;
40	
41	  if (vertices.length < 2 || maneuvers.isEmpty) return result;
42	
43	  for (final cp in checkpoints) {
44	    final (closestIndex, distance) = _closestPointOnPolyline(
45	      vertices,
46	      cp.latitude.toDouble(),
47	      cp.longitude.toDouble(),
48	    );
49	
50	    if (distance > kProximityThresholdMeters) continue;
51	
52	    final maneuverIndex = _findManeuverForOffset(
53	      maneuvers,
54	      closestIndex,
55	      vertices.length,
56	    );
57	
58	    result.putIfAbsent(maneuverIndex, () => []).add(cp);
59	  }
60	
61	  return result;
62	}
63	
64	(double segmentIndex, double distanceMeters) _closestPointOnPolyline(
65	  List<GeoCoordinates> vertices,
66	  double lat,
67	  double lng,
68	) {
69	  double minDistance = double.infinity;
70	  double closestIndex = 0;
71	
72	  for (var i = 0; i < vertices.length - 1; i++) {
73	    final a = vertices[i];
74	    final b = vertices[i + 1];
75	
76	    final t = _projectPointOnSegment(
77	      lat,
78	      lng,
79	      a.latitude,
80	      a.longitude,
81	      b.latitude,
82	      b.longitude,
83	    );
84	
85	    final clampedT = t.clamp(0.0, 1.0);
86	    final projLat = a.latitude + clampedT * (b.latitude - a.latitude);
87	    final projLng = a.longitude + clampedT * (b.longitude - a.longitude);
88	
89	    final dist = _haversineMeters(lat, lng, projLat, projLng);
90	
91	    if (dist < minDistance) {
92	      minDistance = dist;
93	      closestIndex = i + clampedT;
94	    }
95	  }
96	
97	  return (closestIndex, minDistance);
98	}
99	
100	double _projectPointOnSegment(
101	  double px,
102	  double py,
103	  double ax,
104	  double ay,
105	  double bx,
106	  double by,
107	) {
108	  final abx = bx - ax;
109	  final aby = by - ay;
110	  final lengthSquared = abx * abx + aby * aby;
111	  if (lengthSquared == 0) return 0;
112	  return ((px - ax) * abx + (py - ay) * aby) / lengthSquared;
113	}
114	
115	double _haversineMeters(
116	  double lat1,
117	  double lng1,
118	  double lat2,
119	  double lng2,
120	) {
121	  const p = 0.017453292519943295;
122	  final a =
123	      0.5 -
124	      cos((lat1 - lat2) * p) / 2 +
125	      cos(lat2 * p) *
126	          cos(lat1 * p) *
127	          (1 - cos((lng1 - lng2) * p)) /
128	          2;
129	  return 12742 * asin(sqrt(a)) * 1000;
130	}
131	
