import 'dart:math';

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:here_sdk/core.dart';
import 'package:here_sdk/routing.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';

import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';
import 'package:ukcheckpoints_app/features/checkpoints/domain/geoutils.dart';
import 'package:ukcheckpoints_app/features/map/providers/routing_provider.dart';

typedef RouteCheckpointMap = Map<int, List<Checkpoint>>;

final routeCheckpointsProvider =
    Provider<RouteCheckpointMap>((ref) {
  final routeState = ref.watch(routeCalculationProvider);
  final checkpointState = ref.watch(checkpointNotifierProvider);

  final route = routeState.valueOrNull;
  final checkpoints = checkpointState.valueOrNull?.checkpoints;

  if (route == null || checkpoints == null || checkpoints.isEmpty) {
    return {};
  }

  return _computeRouteCheckpoints(
    route.route.geometry,
    route.maneuvers,
    checkpoints,
  );
});

RouteCheckpointMap _computeRouteCheckpoints(
  GeoPolyline polyline,
  List<Maneuver> maneuvers,
  List<Checkpoint> checkpoints,
) {
  final result = <int, List<Checkpoint>>{};
  final vertices = polyline.vertices;

  if (vertices.length < 2 || maneuvers.isEmpty) return result;

  for (final cp in checkpoints) {
    final (closestIndex, distance) = _closestPointOnPolyline(
      vertices,
      cp.latitude.toDouble(),
      cp.longitude.toDouble(),
    );

    if (distance > kProximityThresholdMeters) continue;

    final maneuverIndex = _findManeuverForOffset(
      maneuvers,
      closestIndex,
      vertices.length,
    );

    result.putIfAbsent(maneuverIndex, () => []).add(cp);
  }

  return result;
}

(double segmentIndex, double distanceMeters) _closestPointOnPolyline(
  List<GeoCoordinates> vertices,
  double lat,
  double lng,
) {
  double minDistance = double.infinity;
  double closestIndex = 0;

  for (var i = 0; i < vertices.length - 1; i++) {
    final a = vertices[i];
    final b = vertices[i + 1];

    final t = _projectPointOnSegment(
      lat,
      lng,
      a.latitude,
      a.longitude,
      b.latitude,
      b.longitude,
    );

    final clampedT = t.clamp(0.0, 1.0);
    final projLat = a.latitude + clampedT * (b.latitude - a.latitude);
    final projLng = a.longitude + clampedT * (b.longitude - a.longitude);

    final dist = _haversineMeters(lat, lng, projLat, projLng);

    if (dist < minDistance) {
      minDistance = dist;
      closestIndex = i + clampedT;
    }
  }

  return (closestIndex, minDistance);
}

double _projectPointOnSegment(
  double px,
  double py,
  double ax,
  double ay,
  double bx,
  double by,
) {
  final abx = bx - ax;
  final aby = by - ay;
  final lengthSquared = abx * abx + aby * aby;
  if (lengthSquared == 0) return 0;
  return ((px - ax) * abx + (py - ay) * aby) / lengthSquared;
}

double _haversineMeters(
  double lat1,
  double lng1,
  double lat2,
  double lng2,
) {
  const p = 0.017453292519943295;
  final a =
      0.5 -
      cos((lat1 - lat2) * p) / 2 +
      cos(lat2 * p) *
          cos(lat1 * p) *
          (1 - cos((lng1 - lng2) * p)) /
          2;
  return 12742 * asin(sqrt(a)) * 1000;
}

int _findManeuverForOffset(
  List<Maneuver> maneuvers,
  double offsetInPolyline,
  int totalVertices,
) {
  for (var i = maneuvers.length - 1; i >= 0; i--) {
    if (maneuvers[i].offset <= offsetInPolyline.toInt()) {
      return i;
    }
  }
  return 0;
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:here_sdk/routing.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/map/providers/guidance_provider.dart';
import 'package:ukcheckpoints_app/features/map/providers/routing_provider.dart';

String _bannerFormatDistance(int meters) {
  if (meters >= 1000) {
    return '${(meters / 1609.34).toStringAsFixed(1)} mi';
  }
  return '${(meters * 3.28084).round()} ft';
}

class ManeuverBanner extends ConsumerWidget {
  const ManeuverBanner({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final guidance = ref.watch(navigationGuidanceProvider);
    final routeAsync = ref.watch(routeCalculationProvider);
    final route = routeAsync.valueOrNull;

    if (guidance.isActive) {
      return _GuidanceBanner(guidance: guidance);
    }

    if (route != null) {
      final first = route.maneuvers.firstOrNull;
      if (first == null) return const SizedBox.shrink();
      return _PlannedRouteBanner(maneuver: first);
    }

    return const SizedBox.shrink();
  }
}

class _GuidanceBanner extends StatelessWidget {
  final GuidanceState guidance;

  const _GuidanceBanner({required this.guidance});

  @override
  Widget build(BuildContext context) {
    final action = guidance.currentAction;
    final text = guidance.currentManeuverText ?? 'Continue';
    final nextDist = guidance.nextManeuverDistance;
    final remainingDist = guidance.remainingDistanceMeters;

    final showLookAhead =
        guidance.nextManeuverAction != null &&
        guidance.nextManeuverDistance != null &&
        guidance.nextManeuverDistance! <= 500;

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        if (action != null)
          _CurrentManeuverCard(
            action: action,
            text: text,
            distance: nextDist ?? remainingDist,
          ),
        if (showLookAhead)
          Padding(
            padding: const EdgeInsets.only(top: 2),
            child: _NextManeuverCard(
              action: guidance.nextManeuverAction!,
              text: guidance.nextManeuverText ?? '',
            ),
          ),
      ],
    );
  }
}

class _PlannedRouteBanner extends StatelessWidget {
  final Maneuver maneuver;

  const _PlannedRouteBanner({required this.maneuver});

  @override
  Widget build(BuildContext context) {
    return _CurrentManeuverCard(
      action: maneuver.action,
      text: maneuver.text,
      distance: maneuver.lengthInMeters,
    );
  }
}

class _CurrentManeuverCard extends StatelessWidget {
  final ManeuverAction action;
  final String text;
  final int distance;

  const _CurrentManeuverCard({
    required this.action,
    required this.text,
    required this.distance,
  });

  IconData _actionIcon() {
    return switch (action) {
      ManeuverAction.depart => Icons.radio_button_checked,
      ManeuverAction.arrive => Icons.flag,
      ManeuverAction.leftTurn => Icons.turn_left,
      ManeuverAction.rightTurn => Icons.turn_right,
      ManeuverAction.leftUTurn => Icons.u_turn_left,
      ManeuverAction.rightUTurn => Icons.u_turn_right,
      ManeuverAction.sharpLeftTurn => Icons.turn_sharp_left,
      ManeuverAction.sharpRightTurn => Icons.turn_sharp_right,
      ManeuverAction.slightLeftTurn => Icons.turn_slight_left,
      ManeuverAction.slightRightTurn => Icons.turn_slight_right,
      ManeuverAction.continueOn => Icons.arrow_upward,
      ManeuverAction.leftRamp => Icons.merge,
      ManeuverAction.rightRamp => Icons.merge,
      ManeuverAction.leftFork => Icons.call_split,
      ManeuverAction.middleFork => Icons.call_split,
      ManeuverAction.rightFork => Icons.call_split,
      ManeuverAction.leftExit => Icons.exit_to_app,
      ManeuverAction.rightExit => Icons.exit_to_app,
      ManeuverAction.enterHighwayFromLeft => Icons.add_road,
      ManeuverAction.enterHighwayFromRight => Icons.add_road,
      _ => Icons.straight,
    };
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        color: ThemeColors.bgRaised,
        borderRadius: const BorderRadius.only(
          bottomLeft: Radius.circular(ThemeRadius.rXl),
          bottomRight: Radius.circular(ThemeRadius.rXl),
        ),
        boxShadow: ThemeShadows.lg,
      ),
      padding: const EdgeInsets.fromLTRB(
        ThemeSpacing.sp4,
        ThemeSpacing.sp3,
        ThemeSpacing.sp4,
        ThemeSpacing.sp4,
      ),
      child: Row(
        children: [
          Container(
            width: ThemeSpacing.sp8,
            height: ThemeSpacing.sp8,
            decoration: const BoxDecoration(
              color: ThemeColors.accent,
              shape: BoxShape.circle,
            ),
            child: Center(
              child: Icon(
                _actionIcon(),
                size: 18,
                color: Colors.white,
              ),
            ),
          ),
          const SizedBox(width: ThemeSpacing.sp3),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  'In ${_bannerFormatDistance(distance)}',
                  style: const TextStyle(
                    fontFamily: ThemeFonts.ui,
                    fontSize: 22,
                    fontWeight: FontWeight.w500,
                    height: 1.25,
                    color: ThemeColors.textPrimary,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  text,
                  style: ThemeText.callout.copyWith(
                    color: ThemeColors.textSecondary,
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _NextManeuverCard extends StatelessWidget {
  final ManeuverAction action;
  final String text;

  const _NextManeuverCard({
    required this.action,
    required this.text,
  });

  IconData _actionIcon() {
    return switch (action) {
      ManeuverAction.leftTurn => Icons.turn_left,
      ManeuverAction.rightTurn => Icons.turn_right,
      ManeuverAction.leftUTurn => Icons.u_turn_left,
      ManeuverAction.rightUTurn => Icons.u_turn_right,
      ManeuverAction.sharpLeftTurn => Icons.turn_sharp_left,
      ManeuverAction.sharpRightTurn => Icons.turn_sharp_right,
      ManeuverAction.slightLeftTurn => Icons.turn_slight_left,
      ManeuverAction.slightRightTurn => Icons.turn_slight_right,
      ManeuverAction.continueOn => Icons.arrow_upward,
      _ => Icons.straight,
    };
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        color: ThemeColors.bgSubtle,
        borderRadius: const BorderRadius.only(
          bottomLeft: Radius.circular(ThemeRadius.rLg),
          bottomRight: Radius.circular(ThemeRadius.rLg),
        ),
        boxShadow: [
          BoxShadow(
            blurRadius: 4,
            offset: const Offset(0, 2),
            color: Colors.black.withValues(alpha: 0.06),
          ),
        ],
      ),
      padding: const EdgeInsets.symmetric(
        horizontal: ThemeSpacing.sp4,
        vertical: ThemeSpacing.sp2,
      ),
      child: Row(
        children: [
          Text(
            'Then',
            style: const TextStyle(
              fontFamily: ThemeFonts.ui,
              fontSize: 11,
              fontWeight: FontWeight.w500,
              letterSpacing: 0.5,
              color: ThemeColors.textTertiary,
            ),
          ),
          const SizedBox(width: ThemeSpacing.sp2),
          Icon(_actionIcon(), size: 18, color: ThemeColors.textSecondary),
          const SizedBox(width: ThemeSpacing.sp2),
          Expanded(
            child: Text(
              text,
              style: ThemeText.subheadline.copyWith(
                color: ThemeColors.textPrimary,
              ),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
          ),
        ],
      ),
    );
  }
}

