import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:here_sdk/core.dart';
import 'package:here_sdk/search.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/map/data/vehicle_profile_model.dart';
import 'package:ukcheckpoints_app/features/map/data/vehicle_profile_repository.dart';
import 'package:ukcheckpoints_app/features/map/providers/navigation_provider.dart';
import 'package:ukcheckpoints_app/features/map/widgets/vehicle_profile_sheet.dart';

class NavigationInputBar extends ConsumerStatefulWidget {
  final GeoCoordinates? userLocation;
  final void Function(VehicleProfileModel profile)? onNavigate;

  const NavigationInputBar({
    super.key,
    this.userLocation,
    this.onNavigate,
  });

  @override
  ConsumerState<NavigationInputBar> createState() =>
      _NavigationInputBarState();
}

class _NavigationInputBarState extends ConsumerState<NavigationInputBar> {
  final _originController = TextEditingController();
  final _destController = TextEditingController();
  final _destFocus = FocusNode();
  final _originFocus = FocusNode();
  bool _showDestSuggestions = false;
  bool _showOriginSuggestions = false;

  List<VehicleProfileModel> _profiles = [];
  VehicleProfileModel? _selectedProfile;
  bool _loadingProfiles = true;

  @override
  void initState() {
    super.initState();
    _destFocus.addListener(() {
      setState(() => _showDestSuggestions = _destFocus.hasFocus);
    });
    _originFocus.addListener(() {
      setState(() => _showOriginSuggestions = _originFocus.hasFocus);
    });
    unawaited(_loadProfiles());
  }

  Future<void> _loadProfiles() async {
    final service = ref.read(vehicleProfileRepositoryProvider);
    final profiles = await service.getAll();
    if (!mounted) return;
    setState(() {
      _profiles = profiles;
      _loadingProfiles = false;
      if (profiles.isNotEmpty) {
        _selectedProfile = profiles.first;
      }
    });
  }

  void _openCreateSheet() {
    final service = ref.read(vehicleProfileRepositoryProvider);
    unawaited(
      showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        builder: (_) => VehicleProfileSheet(
          service: service,
          onProfileCreated: () {
            unawaited(_loadProfiles());
          },
        ),
      ),
    );
  }

  @override
  void dispose() {
    _originController.dispose();
    _destController.dispose();
    _destFocus.dispose();
    _originFocus.dispose();
    super.dispose();
  }

  void _useCurrentLocation() {
    final loc = widget.userLocation;
    if (loc == null) return;
    _originController.text = 'Current Location';
    ref.read(navigationRouteProvider.notifier).state = ref
        .read(navigationRouteProvider)
        .copyWith(origin: loc, originLabel: 'Current Location');
  }

  void _swapRoutes() {
    final route = ref.read(navigationRouteProvider);
    if (route.origin == null && route.destination == null) return;

    final tempOrigin = route.origin;
    final tempOriginLabel = route.originLabel;
    final tempDest = route.destination;
    final tempDestLabel = route.destinationLabel;

    _originController.text = tempDestLabel;
    _destController.text = tempOriginLabel;

    ref.read(navigationRouteProvider.notifier).state = NavigationRoute(
      origin: tempDest,
      originLabel: tempDestLabel,
      destination: tempOrigin,
      destinationLabel: tempOriginLabel,
    );
  }

  void _selectOriginSuggestion(Suggestion suggestion) {
    final place = suggestion.place;
    if (place == null) return;
    _originController.text = suggestion.title;
    _originFocus.unfocus();
    ref.read(navigationRouteProvider.notifier).state = ref
        .read(navigationRouteProvider)
        .copyWith(origin: place.geoCoordinates, originLabel: suggestion.title);
    ref.read(destinationSearchProvider.notifier).clear();
  }

  void _selectDestinationSuggestion(Suggestion suggestion) {
    final place = suggestion.place;
    if (place == null) return;
    _destController.text = suggestion.title;
    _destFocus.unfocus();
    ref.read(navigationRouteProvider.notifier).state = ref
        .read(navigationRouteProvider)
        .copyWith(
          destination: place.geoCoordinates,
          destinationLabel: suggestion.title,
        );
    ref.read(destinationSearchProvider.notifier).clear();
  }

  void _onStartTap() {
    if (_selectedProfile != null) {
      widget.onNavigate?.call(_selectedProfile!);
    }
  }

  @override
  Widget build(BuildContext context) {
    final suggestionsAsync = ref.watch(destinationSearchProvider);
    final route = ref.watch(navigationRouteProvider);
    final canNavigate = route.origin != null && route.destination != null;
    final suggestions = suggestionsAsync.valueOrNull ?? [];
    final isSearching = suggestionsAsync is AsyncLoading;
    final routeSwappable = route.origin != null || route.destination != null;

    return SingleChildScrollView(
      padding: const EdgeInsets.symmetric(horizontal: ThemeSpacing.sp4),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const SizedBox(height: ThemeSpacing.sp3),
          _VehicleChip(
            profiles: _profiles,
            selectedProfile: _selectedProfile,
            isLoading: _loadingProfiles,
            onCreateNew: _openCreateSheet,
            onChanged: (p) => setState(() => _selectedProfile = p),
          ),
          const SizedBox(height: ThemeSpacing.sp3),

          _RouteCard(
            originController: _originController,
            destController: _destController,
            originFocus: _originFocus,
            destFocus: _destFocus,
            isSearching: isSearching,
            suggestions: suggestions,
            routeSwappable: routeSwappable,
            showOriginSuggestions: _showOriginSuggestions,
            showDestSuggestions: _showDestSuggestions,
            onOriginChanged: (v) {
              ref.read(destinationSearchProvider.notifier).query(v);
            },
            onDestChanged: (v) {
              ref.read(destinationSearchProvider.notifier).query(v);
            },
            onOriginSuggestionSelected: _selectOriginSuggestion,
            onDestSuggestionSelected: _selectDestinationSuggestion,
            onUseCurrentLocation: _useCurrentLocation,
            onSwapRoutes: _swapRoutes,
            onClearDest: () {
              _destController.clear();
              ref.read(destinationSearchProvider.notifier).clear();
            },
          ),

          if (canNavigate) ...[
            const SizedBox(height: ThemeSpacing.sp4),
            SizedBox(
              width: double.infinity,
              height: 48,
              child: ElevatedButton.icon(
                onPressed: _onStartTap,
                icon: const Icon(Icons.navigation, size: 20),
                label: const Text('Start navigation'),
              ),
            ),
          ],
          const SizedBox(height: ThemeSpacing.sp3),
        ],
      ),
    );
  }
}

class _VehicleChip extends StatelessWidget {
  final List<VehicleProfileModel> profiles;
  final VehicleProfileModel? selectedProfile;
  final bool isLoading;
  final VoidCallback onCreateNew;
  final void Function(VehicleProfileModel) onChanged;

  const _VehicleChip({
    required this.profiles,
    required this.selectedProfile,
    required this.isLoading,
    required this.onCreateNew,
    required this.onChanged,
  });

  IconData _typeIcon(int index) {
    return switch (index) {
      0 => Icons.directions_car,
      1 => Icons.local_shipping,
      4 => Icons.pedal_bike,
      _ => Icons.directions_car,
    };
  }

  @override
  Widget build(BuildContext context) {
    if (isLoading) {
      return const SizedBox(
        height: 40,
        child: Center(
          child: SizedBox(
            width: 16,
            height: 16,
            child: CircularProgressIndicator(strokeWidth: 2),
          ),
        ),
      );
    }

    return Container(
      height: 44,
      padding: const EdgeInsets.symmetric(horizontal: ThemeSpacing.sp3),
      decoration: BoxDecoration(
        color: ThemeColors.bgRaised,
        borderRadius: ThemeRadius.brMd,
        border: Border.all(color: ThemeColors.border),
      ),
      child: DropdownButtonHideUnderline(
        child: DropdownButton<VehicleProfileModel>(
          isExpanded: true,
          value: selectedProfile,
          icon: const Icon(Icons.keyboard_arrow_down, size: 20),
          style: ThemeText.callout.copyWith(
            color: ThemeColors.textPrimary,
          ),
          selectedItemBuilder: (_) {
            return profiles.map((p) {
              return Row(
                children: [
                  Icon(_typeIcon(p.vehicleTypeIndex), size: 18, color: ThemeColors.accent),
                  const SizedBox(width: ThemeSpacing.sp2),
                  Text(p.name, style: ThemeText.callout),
                ],
              );
            }).toList();
          },
          items: [
            ...profiles.map(
              (p) => DropdownMenuItem(
                value: p,
                child: Row(
                  children: [
                    Icon(_typeIcon(p.vehicleTypeIndex), size: 20, color: ThemeColors.accent),
                    const SizedBox(width: ThemeSpacing.sp3),
                    Expanded(child: Text(p.name, overflow: TextOverflow.ellipsis)),
                  ],
                ),
              ),
            ),
            const DropdownMenuItem<VehicleProfileModel>(
              value: null,
              child: Row(
                children: [
                  Icon(Icons.add_circle_outline, size: 20, color: ThemeColors.accent),
                  SizedBox(width: ThemeSpacing.sp3),
                  Text('Create new profile'),
                ],
              ),
            ),
          ],
          onChanged: (p) {
            if (p == null) {
              onCreateNew();
            } else {
              onChanged(p);
            }
          },
        ),
      ),
    );
  }
}

class _RouteCard extends StatelessWidget {
  final TextEditingController originController;
  final TextEditingController destController;
  final FocusNode originFocus;
  final FocusNode destFocus;
  final bool isSearching;
  final List<Suggestion> suggestions;
  final bool routeSwappable;
  final bool showOriginSuggestions;
  final bool showDestSuggestions;
  final ValueChanged<String> onOriginChanged;
  final ValueChanged<String> onDestChanged;
  final void Function(Suggestion) onOriginSuggestionSelected;
  final void Function(Suggestion) onDestSuggestionSelected;
  final VoidCallback onUseCurrentLocation;
  final VoidCallback onSwapRoutes;
  final VoidCallback onClearDest;

  const _RouteCard({
    required this.originController,
    required this.destController,
    required this.originFocus,
    required this.destFocus,
    required this.isSearching,
    required this.suggestions,
    required this.routeSwappable,
    required this.showOriginSuggestions,
    required this.showDestSuggestions,
    required this.onOriginChanged,
    required this.onDestChanged,
    required this.onOriginSuggestionSelected,
    required this.onDestSuggestionSelected,
    required this.onUseCurrentLocation,
    required this.onSwapRoutes,
    required this.onClearDest,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          decoration: BoxDecoration(
            color: ThemeColors.bgRaised,
            borderRadius: ThemeRadius.brLg,
            border: Border.all(color: ThemeColors.borderStrong),
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              _RouteField(
                controller: originController,
                focusNode: originFocus,
                hint: 'Your location',
                icon: Icons.circle,
                iconColor: ThemeColors.accent,
                iconSize: 12,
                onChanged: onOriginChanged,
                trailing: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    _FieldAction(
                      icon: Icons.my_location,
                      onTap: onUseCurrentLocation,
                    ),
                    if (routeSwappable)
                      _FieldAction(
                        icon: Icons.swap_vert,
                        onTap: onSwapRoutes,
                      ),
                  ],
                ),
              ),
              const Divider(height: 1, indent: 48, endIndent: 16),
              _RouteField(
                controller: destController,
                focusNode: destFocus,
                hint: 'Where to?',
                icon: Icons.radio_button_checked,
                iconColor: ThemeColors.danger,
                iconSize: 12,
                onChanged: onDestChanged,
                trailing:
                    destController.text.isNotEmpty
                        ? _FieldAction(
                          icon: Icons.close,
                          onTap: onClearDest,
                        )
                        : null,
              ),
            ],
          ),
        ),

        if (showOriginSuggestions && isSearching)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: ThemeSpacing.sp4),
            child: Center(
              child: SizedBox(
                width: 20,
                height: 20,
                child: CircularProgressIndicator(strokeWidth: 2),
              ),
            ),
          ),

        if (showOriginSuggestions && !isSearching && suggestions.isNotEmpty)
          _SuggestionList(
            suggestions: suggestions,
            icon: Icons.circle,
            iconColor: ThemeColors.accent,
            iconSize: 12,
            onSelected: onOriginSuggestionSelected,
          ),

        if (showDestSuggestions && isSearching)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: ThemeSpacing.sp4),
            child: Center(
              child: SizedBox(
                width: 20,
                height: 20,
                child: CircularProgressIndicator(strokeWidth: 2),
              ),
            ),
          ),

        if (showDestSuggestions && !isSearching && suggestions.isNotEmpty)
          _SuggestionList(
            suggestions: suggestions,
            icon: Icons.radio_button_checked,
            iconColor: ThemeColors.danger,
            iconSize: 12,
            onSelected: onDestSuggestionSelected,
          ),
      ],
    );
  }
}

