class _SuggestionList extends StatelessWidget {
  final List<Suggestion> suggestions;
  final IconData icon;
  final Color iconColor;
  final double iconSize;
  final void Function(Suggestion) onSelected;

  const _SuggestionList({
    required this.suggestions,
    required this.icon,
    required this.iconColor,
    required this.iconSize,
    required this.onSelected,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      margin: const EdgeInsets.only(top: ThemeSpacing.sp2),
      decoration: BoxDecoration(
        color: ThemeColors.bgRaised,
        borderRadius: ThemeRadius.brLg,
        border: Border.all(color: ThemeColors.border),
      ),
      child: ClipRRect(
        borderRadius: ThemeRadius.brLg,
        child: ListView.separated(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          padding: EdgeInsets.zero,
          itemCount: suggestions.length,
          separatorBuilder: (context, index) => const Divider(
            height: 1,
            indent: 48,
            endIndent: 16,
          ),
          itemBuilder: (context, index) {
            final s = suggestions[index];
            final secondary = s.place?.address?.addressText ?? '';

            return ListTile(
              dense: true,
              visualDensity: VisualDensity.compact,
              leading: Icon(icon, size: iconSize, color: iconColor),
              title: Text(
                s.title,
                style: ThemeText.callout,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
              subtitle: secondary.isNotEmpty
                  ? Text(
                    secondary,
                    style: ThemeText.footnote,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  )
                  : null,
              onTap: () => onSelected(s),
            );
          },
        ),
      ),
    );
  }
}

